/* @autogenerated */
package net.civeira.phylax.feature.observe.anomaly;

import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.metric.MetricDeriver;
import net.civeira.phylax.feature.observe.metric.ObserveMetrics;
import net.civeira.phylax.feature.observe.store.ObsLog;

/**
 * Anomalies and new log patterns: the baselines are rebuilt every hour from the hourly metrics of
 * the last four weeks, the detection runs every minute on the last minutes, and the patterns are
 * observed in the writer. The result is kept in memory for the viewer and the anomaly alert rules.
 */
@ApplicationScoped
@Slf4j
public class ObserveInsights {

  private static final long DAY = 24 * MetricDeriver.HOUR;

  private final ObserveMetrics metrics;
  private final AnomalyDetector detector;
  private final LogPatterns patterns;
  private final int windowMinutes;
  private volatile Baselines baselines = Baselines.empty();
  private volatile long baselinesHour = -1;
  private volatile List<AnomalyDetector.Anomaly> current = List.of();

  public ObserveInsights(final ObserveMetrics metrics,
      final @ConfigProperty(name = "app.observe.anomaly.sigma", defaultValue = "3") double sigma,
      final @ConfigProperty(name = "app.observe.anomaly.min-requests",
          defaultValue = "20") long minRequests,
      final @ConfigProperty(name = "app.observe.anomaly.window-minutes",
          defaultValue = "15") int windowMinutes,
      final @ConfigProperty(name = "app.observe.path",
          defaultValue = "data/observability") String path) {
    this.metrics = metrics;
    this.detector = new AnomalyDetector(sigma, minRequests);
    this.windowMinutes = Math.max(5, windowMinutes);
    this.patterns = new LogPatterns(Path.of(path));
  }

  public void start() {
    patterns.load();
  }

  /** Every minute: the baselines if the hour changed, and the anomalies of now. */
  public void minute() {
    long now = System.currentTimeMillis();
    long hour = now / MetricDeriver.HOUR;
    if (hour != baselinesHour) {
      baselines =
          Baselines.of(metrics.raw(Set.of(), now - 28 * DAY, hour * MetricDeriver.HOUR, true));
      baselinesHour = hour;
    }
    long from = (now / MetricDeriver.MINUTE - windowMinutes) * MetricDeriver.MINUTE;
    current = detector.detect(baselines,
        metrics.raw(Set.of(), from, now / MetricDeriver.MINUTE * MetricDeriver.MINUTE, false),
        windowMinutes, now);
  }

  /** The WARN or higher logs of a batch of the writer. */
  public void observe(final List<ObsLog> logs) {
    patterns.observe(logs);
  }

  public List<AnomalyDetector.Anomaly> anomalies() {
    return current;
  }

  /** For the viewer: current anomalies and the log patterns first seen in the range. */
  public Map<String, Object> view(final long since) {
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("anomalies", current);
    result.put("patterns", patterns.since(since));
    return result;
  }
}
